import Foundation

/// Static additions for the anime features. Unknown keys continue through the main catalog.
/// No preferences, files or network access occurs during lookup or initialization.
enum AnimeFeatureLocalization {
    private struct Entry: Sendable {
        let chinese: String
        let english: String
        let japanese: String
        let spanish: String

        init(_ chinese: String, _ english: String, _ japanese: String, _ spanish: String) {
            self.chinese = chinese
            self.english = english
            self.japanese = japanese
            self.spanish = spanish
        }

        func value(_ language: LocalizationService.Language) -> String {
            switch language {
            case .chinese: return chinese
            case .english: return english
            case .japanese: return japanese
            case .spanish: return spanish
            }
        }
    }

    static func value(_ key: String, language: LocalizationService.Language) -> String? {
        entries[key]?.value(language)
    }

